import { describe, it, expect } from 'vitest';
import { PDFParse } from 'pdf-parse';
import { getDocument } from 'pdfjs-dist/legacy/build/pdf.mjs';
// T-19 (CVB-18). Not yet implemented: renderCvPdf(cv) is the seam under test.
import { renderCvPdf } from './render.js';
import type { CvResponse, CvExperience, CvBullet } from '../cv/types.js';

// Text is extracted back from the generated bytes. A rasterised page has no
// text layer and fails every "contains" assertion below.
async function parsePdf(bytes: Uint8Array) {
  const parser = new PDFParse({ data: new Uint8Array(bytes) });
  const text = await parser.getText();
  const info = await parser.getInfo({ parsePageInfo: true });
  return { text: text.text, pages: info.pages };
}

function bullet(i: number, text: string): CvBullet {
  return { id: `b${i}`, text, factIds: [], userEdited: false };
}

function experience(i: number, employer: string, role: string, bullets: CvBullet[]): CvExperience {
  return {
    id: `e${i}`,
    employer,
    role,
    period: 'Mar 2019 – Present',
    order: i,
    relevance: 0.5,
    userEdited: false,
    bullets,
  };
}

function cvFixture(overrides: Partial<CvResponse> = {}): CvResponse {
  return {
    id: '00000000-0000-4000-8000-000000000001',
    title: 'Ada Lovelace – Backend Engineer',
    targetRole: 'Backend Engineer',
    state: 'ready',
    version: 3,
    updatedAt: '2026-10-20T10:00:00.000Z',
    contact: {
      fullName: 'Ada Lovelace',
      email: 'ada@example.com',
      phone: '+44 20 7946 0000',
      location: 'London',
      links: [],
    },
    summary: { text: 'Backend engineer who ships fast builds.', factIds: [], userEdited: false },
    experience: [
      experience(0, 'Babbage Works', 'Lead Engineer', [bullet(0, 'Cut build time by 40%')]),
      experience(1, 'Analytical Engines', 'Engineer', [bullet(1, 'Shipped the difference engine driver')]),
    ],
    education: [
      { id: 'ed0', institution: 'University of London', degree: 'BSc Mathematics', period: '2011 – 2014', order: 0, userEdited: false },
    ],
    skills: [{ id: 's0', name: 'TypeScript', group: 'Languages', factIds: [], userEdited: false }],
    questions: [],
    facts: [],
    ...overrides,
  };
}

describe('renderCvPdf (F-007, ADR-005)', () => {
  it('produces a PDF whose first page is exactly A4, 595 x 842 pt', async () => {
    const bytes = await renderCvPdf(cvFixture());
    const { pages } = await parsePdf(bytes);
    expect(pages.length).toBeGreaterThanOrEqual(1);
    expect(pages[0]).toMatchObject({ width: 595, height: 842 });
  });

  it('writes a real text layer: name, employer names and a bullet are selectable strings', async () => {
    const bytes = await renderCvPdf(cvFixture());
    const { text } = await parsePdf(bytes);
    expect(text).toContain('Ada Lovelace');
    expect(text).toContain('Babbage Works');
    expect(text).toContain('Analytical Engines');
    expect(text).toContain('Cut build time by 40%');
  });

  it('renders Latin-1 supplement and Cyrillic from an embedded Unicode font, not blanks or boxes', async () => {
    const bytes = await renderCvPdf(
      cvFixture({
        contact: { fullName: 'Анна Петрова', email: 'anna@example.com', links: [], location: 'Zürich' },
        experience: [experience(0, 'Café Москва', 'Инженер', [bullet(0, 'Построила сервис для Zürich')])],
      }),
    );
    const { text } = await parsePdf(bytes);
    expect(text).toContain('Анна Петрова');
    expect(text).toContain('Zürich');
    expect(text).toContain('Café Москва');
    expect(text).toContain('Построила сервис для Zürich');
  });

  it('paginates long content and keeps the last bullet on a later page, not clipped', async () => {
    const many = Array.from({ length: 60 }, (_, i) =>
      bullet(i, `Delivered measurable outcome number ${i + 1} for the platform team`),
    );
    const bytes = await renderCvPdf(cvFixture({ experience: [experience(0, 'Babbage Works', 'Lead Engineer', many)] }));
    const { text, pages } = await parsePdf(bytes);
    expect(pages.length).toBeGreaterThanOrEqual(2);
    expect(pages.every((p) => p.width === 595 && p.height === 842)).toBe(true);
    expect(text).toContain('Delivered measurable outcome number 1 for the platform team');
    expect(text).toContain('Delivered measurable outcome number 60 for the platform team');
  });

  it('omits empty optional sections instead of printing empty headings', async () => {
    const bytes = await renderCvPdf(cvFixture({ education: [], skills: [] }));
    const { text } = await parsePdf(bytes);
    expect(text).toContain('Babbage Works');
    expect(text).not.toMatch(/Education/);
    expect(text).not.toMatch(/Skills/);
  });

  it('prints the education and skills sections when they have content', async () => {
    const bytes = await renderCvPdf(cvFixture());
    const { text } = await parsePdf(bytes);
    expect(text).toContain('University of London');
    expect(text).toContain('TypeScript');
  });

  it('keeps every text run at least 15 mm (42.5 pt) from each page edge, on every page', async () => {
    const MIN = 42.5;
    // pdfjs reports the em box as height; ink (ascenders, capitals) reaches about 0.8 of it.
    const ASCENDER = 0.8;
    const many = Array.from({ length: 60 }, (_, i) =>
      bullet(i, `Delivered measurable outcome number ${i + 1} for the platform team, including a long tail of detail so the line wraps near the right margin`),
    );
    const bytes = await renderCvPdf(cvFixture({ experience: [experience(0, 'Babbage Works', 'Lead Engineer', many)] }));
    const doc = await getDocument({ data: new Uint8Array(bytes), useSystemFonts: false }).promise;
    expect(doc.numPages).toBeGreaterThanOrEqual(2);
    for (let n = 1; n <= doc.numPages; n++) {
      const page = await doc.getPage(n);
      const [, , pageW, pageH] = page.view;
      const content = await page.getTextContent();
      const runs = content.items.filter((it) => 'str' in it && it.str.trim() !== '') as Array<{
        str: string;
        width: number;
        height: number;
        transform: number[];
      }>;
      expect(runs.length).toBeGreaterThan(0);
      for (const r of runs) {
        const x = r.transform[4]!;
        const y = r.transform[5]!; // baseline, measured from the bottom edge
        expect(x, `left of "${r.str}" p${n}`).toBeGreaterThanOrEqual(MIN);
        expect(pageW - (x + r.width), `right of "${r.str}" p${n}`).toBeGreaterThanOrEqual(MIN);
        expect(y, `bottom of "${r.str}" p${n}`).toBeGreaterThanOrEqual(MIN);
        expect(pageH - (y + r.height * ASCENDER), `top of "${r.str}" p${n}`).toBeGreaterThanOrEqual(MIN);
      }
    }
  });
});
